# 使用适用于 Linux 的 AWS SDK 向 Amazon S3 上传对象

以下代码示例展示如何向 Amazon S3 上传对象。

```
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import software.amazon.awssdk.services.s3.model.S3Exception;
import software.amazon.awssdk.services.s3.model.PutObjectResponse;
import software.amazon.awssdk.core.sync.RequestBody;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

```

## 场景

本示例使用 `PutObject` 上传一个文件。

```
public class PutObject {
    public static void main(String[] args) {
        final String USAGE = "\n" +
                "用法：\n" +
                "    <bucketName> <objectKey> <filePath>\n\n" +
                "其中：\n" +
                "    bucketName - 存储桶的名称。\n" +
                "    objectKey - 对象的键（例如 filename.ext）。\n" +
                "    filePath - 要上传的文件的完整路径和文件名。\n";

        if (args.length != 3) {
            System.out.println(USAGE);
            System.exit(1);
        }

        String bucketName = args[0];
        String objectKey = args[1];
        String filePath = args[2];

        Region region = Region.US_EAST_1;
        S3Client s3 = S3Client.builder().region(region).build();

        putS3Object(s3, bucketName, objectKey, filePath);
    }

    public static void putS3Object(S3Client s3, String bucketName, String objectKey, String filePath) {
        try {
            Map<String, String> metadata = new HashMap<>();
            metadata.put("x-amz-meta-myVal", "test");

            PutObjectRequest putObjectRequest = PutObjectRequest.builder()
                    .bucket(bucketName)
                    .key(objectKey)
                    .metadata(metadata)
                    .build();

            RequestBody requestBody = RequestBody.fromFile(new File(filePath));

            PutObjectResponse response = s3.putObject(putObjectRequest, requestBody);

            System.out.println("文件 " + filePath + " 已成功上传到存储桶 " + bucketName + "，对象键为 " + objectKey);
        } catch (S3Exception e) {
            System.err.println(e.awsErrorDetails().errorMessage());
            System.exit(1);
        }
    }
}
```

